(* [comment removed for export] *)
Hypothesis LIT_MSG : exists l, In (0x2b060, l) LEPT_LITS.
Hypothesis LIT_FN : exists l, In (0x2b040, l) LEPT_LITS.
(* [comment removed for export] *)
Hypothesis NCLOOP : bc_nc_loop_stmt.
Hypothesis KIDXLOOP : bc_kidx_stmt.
